import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Register.css';
import HomeIcon from '../Common/HomeIcon';


function Register() {
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
  
    if (!username || !email || !password || !confirmPassword) {
      alert('Completează toate câmpurile!');
      return;
    }
  
    if (password !== confirmPassword) {
      alert('Parolele nu se potrivesc!');
      return;
    }
  
    fetch('http://localhost:8080/users/register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ username, email, password })
    })
      .then(res => {
        if (res.status === 409) {
          return res.text().then(msg => { throw new Error(msg); });
        }
        if (!res.ok) {
          throw new Error("Eroare la înregistrare!");
        }
        return res.text();
      })
      .then(data => {
        alert(data); // "User registered successfully."
        setSubmitted(true);
      })
      .catch(error => {
        alert(error.message);
      });
  };
  
  return (
    <div className="register-container">
      <HomeIcon />
      <h1>Înregistrare</h1>
      
      <form onSubmit={handleSubmit}>
        <input type="text"   placeholder="Username"  value={username}  onChange={(e) => setUsername(e.target.value)} />
        <input type="email"  placeholder="Email"     value={email}     onChange={(e) => setEmail(e.target.value)}/>
        <input type="password"  placeholder="Parolă"  value={password} onChange={(e) => setPassword(e.target.value)}/>
        <input type="password"  placeholder="Confirmă parola"  value={confirmPassword}  onChange={(e) => setConfirmPassword(e.target.value)} />
        
        <button type="submit">Înregistrează-te</button>

        <p style={{ textAlign: 'center', marginTop: '15px' }}> Ai deja un cont? <Link to="/login">Autentifică-te</Link></p>
      </form>

      {submitted && (
        <p style={{ color: 'green' }}> Utilizator înregistrat cu succes! </p>
      )}
    </div>
  );
}

export default Register;
